"""Восьмишаговый делитель D4DF, байтовый остаток и дополненное частное."""
FUNCTIONS={0xD4DF:('DividePreviewSlopeByte','Восемь шагов деления горизонтальной длины ребра с дополненным частным и остатком')}
ENDS={0xD4DF:0xD518}
DOCUMENTS={('D3D',0xD4DF):('PreviewSlopeDivision','байтовое деление, Carry, дополненное частное, нулевой делитель и точные флаги')}
LABELS={('D3D',0xD4DF+7*i):'Step'+str(i+1) for i in range(1,8)}
LABELS['D3D',0xD517]='Return'
CONTRACTS={('D3D',0xD4DF):(['HL сохраняется, DE содержит D как делитель и E как делимое', 'BC сохраняется, AF содержит A как начальный старший остаток и Carry как начальный бит регистра E', 'в четырёх найденных вызовах A=0 и Carry=0, выбран банк 4, IRQ и NMI не вмешиваются', 'SP указывает на адрес CPU-возврата, дополнительных байтов под ним не требуется'], ['HL сохраняется, D сохраняется, E=(входной Carry*128) OR ((частное XOR 255)>>1), BC сохраняется', 'A содержит байтовый остаток, Carry младший бит дополненного частного', 'при входном A=0 и D>0 частное равно входному E DIV D, остаток входному E MOD D', 'F соответствует последнему SUB D либо восстанавливающему ADD A, D, при D=0 F=(входной E AND A8) OR (40 при E=0) OR 02', "HL', DE', BC', AF', IX, IY, I, IM и IFF сохраняются", 'последующий RL E объединяет возвращённые E и Carry в полное дополненное частное', 'SP после RET равен входному+2, записей в память нет', 'полный M1 равен 41 плюс число единиц дополненного частного, от 41 до 49, бит 7 R сохраняется'], ['E, AF, R'], ['восемь шагов развёрнуты, счётчик и обращения к таблицам не требуются', 'каждый шаг переносит следующий старший бит исходного E в байтовый остаток A', 'при заёме остаток восстанавливается, Carry становится следующим битом дополненного частного', 'старший девятый разряд после RLA теряется перед SUB, для произвольного A это не полное деление слова A:E', 'при D=0 проверки нет, возвращается A равный исходному E, E равный входному Carry*128 и Carry=0', 'входной Carry влияет только на старший бит возвращённого E, при объединении полного частного он теряется', 'четыре найденных вызова находятся в D2BC, D319, D386 и D3E0, профиль вызывающих проходов рассмотрен в PreviewPolygonFill.md и не подменяется локальным договором делителя'])}
COMMENTS={}
for step in range(8):
 p=0xD4DF+7*step
 COMMENTS[p]=(['-----------------------------------------','Шаг '+str(step+1)+' из восьми','-----------------------------------------','перенос следующего бита делимого в Carry, предыдущий Carry входит в регистр частного'],None)
 COMMENTS[p+2]=(['расчёт байтового пробного остатка с очередным битом делимого, девятый разряд не сохраняется'],None)
 COMMENTS[p+3]=(['проверка возможности вычесть делитель из пробного остатка'],None)
 COMMENTS[p+4]=([], 'переход, если пробный остаток не меньше делителя, оставить результат вычитания')
 COMMENTS[p+6]=(['восстановление байтового остатка после заёма, Carry задаёт единицу дополненного частного'],None)
COMMENTS[0xD517]=(['-----------------------------------------','возврат последнего бита дополненного частного в Carry без заключительного RL E'],None)


def name_operands(region,address,operation):
 if region=='D3D' and address==0xD4DF:
  for (_,pointer),label in LABELS.items():
   operation=operation.replace('#'+format(pointer,'04X'),'@D3D.DividePreviewSlopeByte.'+label)
 return operation
